(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.018-t*0.22)*18+Math.sin(x*0.015+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8+Math.cos((x-y)*0.008-t*0.12)*6;
  const w2y = Math.cos((x-y)*0.01-t*0.13)*8+Math.sin((x+y)*0.007+t*0.17)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110,80+Math.cos(t*0.35)*60,0.075,2.1,0.8],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*60,0.09,1.8,1.2],
    [240+Math.sin(t*0.28+2)*150,120+Math.cos(t*0.42+1)*100,0.055,2.5,0.6],
    [100+Math.cos(t*0.7+1)*90,190+Math.sin(t*0.55+3)*70,0.11,1.6,1.4],
    [380+Math.sin(t*0.38+4)*100,50+Math.cos(t*0.8+2)*80,0.065,2.8,0.9],
    [240+Math.cos(t*0.32+5)*130,210+Math.sin(t*0.5)*90,0.085,2.0,1.1],
    [60+Math.sin(t*0.6+3)*70,60+Math.cos(t*0.4+1)*50,0.1,1.4,1.5],
    [420+Math.cos(t*0.35+2)*80,180+Math.sin(t*0.65+4)*60,0.07,2.4,0.7]
  ];
  let aS=0,iS=0,dS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=1/(1+d*0.003);
    aS+=Math.sin(d*f-t*sp+ph)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+ph+1.8)*w;
    dS+=Math.cos(d*f*1.3-t*sp*0.8+ph*2.1)*w*0.5;
  }
  const aN=aS/6.5,iN=iS/6.5,dN=dS/6.5;
  const bg=(Math.sin(sx*0.035+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*0.95))/2;
  const bg2=(Math.sin((sx+sy)*0.1+t*2.2)+Math.sin((sx-sy)*0.09-t*1.8)+Math.sin(sx*0.06+sy*0.08-t*1.5))/3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2+t*1.8);
  const spiral=(sp1+sp2+sp3)/3;
  const voronoi=(()=>{let m=99;for(const[sX,sY]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);if(d<m)m=d;}return Math.sin(m*0.15-t*1.5)*0.3;})();
  const react=Math.tanh((aN-iN*0.65+dN*0.3+bg*0.25+bg2*0.2+spiral*0.35+voronoi)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro=(Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)+Math.sin((sx*0.2+sy*0.25)*t*0.3))*0.08;
  const blend=react*0.65+cell*0.2+micro;
  const v=blend*0.5+0.5;
  const pal=[
    [12,8,42],[18,25,85],[15,60,115],[10,100,125],
    [25,150,135],[80,175,120],[170,190,75],
    [220,175,60],[230,130,55],[210,80,60],
    [180,50,65],[120,25,70],[60,15,55],[12,8,42]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const edge=Math.abs(react)>0.65?1.12:1.0;
  const glow=Math.max(0,react)*0.15;
  const lum=0.82+Math.sin(react*Math.PI)*0.18;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*50)|0)
  ];
}
